@IsTest
private class OwnedHeaderNullIsolation {
    private static Map<String,Object> baseline() {
        return new Map<String,Object>{
            'entityName'=>'Account','changeType'=>'UPDATE','changeOrigin'=>'owned',
            'transactionKey'=>'owned-tx','sequenceNumber'=>7,'commitTimestamp'=>1700000000123L,
            'commitUser'=>'005000000000001AAA','commitNumber'=>42L,
            'recordIds'=>new List<String>{'001000000000001AAA','001000000000002AAA'},
            'changedFields'=>new List<String>{'Name'},'nulledFields'=>new List<String>{'Industry'},
            'diffFields'=>new List<String>{'Description'}
        };
    }
    private static String oneNull(String fieldName) {
        Map<String,Object> payload=baseline();
        payload.put(fieldName,null);
        return JSON.serialize(payload);
    }
    private static String allNull() {
        Map<String,Object> payload=baseline();
        for(String fieldName:payload.keySet()) payload.put(fieldName,null);
        return JSON.serialize(payload);
    }
    private static void observe(String cell,Boolean strict,String input) {
        Object observed;
        String phase='deserialize';
        try {
            EventBus.ChangeEventHeader header=(EventBus.ChangeEventHeader)(strict
                ?JSON.deserializeStrict(input,EventBus.ChangeEventHeader.class)
                :JSON.deserialize(input,EventBus.ChangeEventHeader.class));
            phase='readFields';
            if(header==null) observed=new List<Object>{'null'};
            else observed=new List<Object>{'value',header.entityName,header.changeType,header.changeOrigin,
            header.transactionKey,header.sequenceNumber,header.commitTimestamp,header.commitUser,
            header.commitNumber,header.recordIds,header.changedFields,header.nulledFields,header.diffFields};
            phase='complete';
        } catch(Exception issue) {
            observed=new List<Object>{'exception',issue.getTypeName(),issue.getMessage()};
        }
        System.assert(false,'HEADER_NULL_OBSERVATION|'+JSON.serialize(new Map<String,Object>{
            'cell'=>cell,'strict'=>strict,'phase'=>phase,'observed'=>observed
