// Owned observations only: no semantic expectations are asserted.
Map<String,Object> baseline=new Map<String,Object>{
            'entityName'=>'Account','changeType'=>'UPDATE','changeOrigin'=>'owned',
            'transactionKey'=>'owned-tx','sequenceNumber'=>7,'commitTimestamp'=>1700000000123L,
            'commitUser'=>'005000000000001AAA','commitNumber'=>42L,
            'recordIds'=>new List<String>{'001000000000001AAA','001000000000002AAA'},
            'changedFields'=>new List<String>{'Name'},'nulledFields'=>new List<String>{'Industry'},
            'diffFields'=>new List<String>{'Description'}
        };
List<String> fields=new List<String>{'entityName','changeType','changeOrigin','transactionKey','sequenceNumber','commitTimestamp','commitUser','commitNumber','recordIds','changedFields','nulledFields','diffFields'};
Map<String,String> inputs=new Map<String,String>();
List<String> cells=new List<String>();
for(String fieldName:fields) {
    Map<String,Object> payload=baseline.clone();
    payload.put(fieldName,null);
    String cell='null_'+fieldName;
    inputs.put(cell,JSON.serialize(payload));
    cells.add(cell);
}
inputs.put('baseline',JSON.serialize(baseline));
inputs.put('omitted','{}');
inputs.put('rootNull','null');
inputs.put('priorComposite','{"entityName":null,"sequenceNumber":null,"commitTimestamp":null,"recordIds":null}');
Map<String,Object> allNull=baseline.clone();
for(String fieldName:fields) allNull.put(fieldName,null);
inputs.put('allNull',JSON.serialize(allNull));
cells.addAll(new List<String>{'baseline','omitted','rootNull','priorComposite','allNull'});
List<Object> observations=new List<Object>();
for(Boolean strict:new List<Boolean>{false,true}) {
    for(String cell:cells) {
        Object observed;
        String phase='deserialize';
        try {
            EventBus.ChangeEventHeader header=(EventBus.ChangeEventHeader)(strict
                ?JSON.deserializeStrict(inputs.get(cell),EventBus.ChangeEventHeader.class)
                :JSON.deserialize(inputs.get(cell),EventBus.ChangeEventHeader.class));
            phase='readFields';
            if(header==null) observed=new List<Object>{'null'};
            else observed=new List<Object>{'value',header.entityName,header.changeType,header.changeOrigin,
            header.transactionKey,header.sequenceNumber,header.commitTimestamp,header.commitUser,
            header.commitNumber,header.recordIds,header.changedFields,header.nulledFields,header.diffFields};
            phase='complete';
        } catch(Exception issue) {
            observed=new List<Object>{'exception',issue.getTypeName(),issue.getMessage()};
        }
        observations.add(new Map<String,Object>{'cell'=>cell,'strict'=>strict,'phase'=>phase,'observed'=>observed});
    }
}
System.debug('HEADER_NULL_ANONYMOUS|'+JSON.serialize(new Map<String,Object>{'cells'=>observations}));

